/* sfx_play_test.c — unit test for src/sfx_play.c. Synthetic data only.
 *
 * Every clip here is generated by the builders below; no byte from a retail
 * file appears in this program, and the only decoded audio comes from a
 * hand-made ABK built further down (same builder shape as tools/sfx_bank_test.c,
 * reproduced here because that file is not shared).
 *
 * Clip buffers are malloc'd at exactly `frames` long on purpose: the
 * interpolator reading one past the end is then an ASan error instead of a
 * silent read of a spare slot in an oversized static array.
 *
 * build: cc -O2 -std=c99 -Wall -Wextra -Werror -Isrc tools/sfx_play_test.c
 *        src/sfx_play.c src/sfx_bank.c -lm
 */
#include "sfx_play.h"

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int nchecks = 0, nfail = 0;

#define CHECK(cond) do {                                        \
        nchecks++;                                              \
        if (!(cond)) {                                          \
            nfail++;                                            \
            printf("FAIL %s:%d  %s\n", __FILE__, __LINE__, #cond);\
        }                                                       \
    } while (0)

#define RATE 44100u                       /* the game's device rate */
#define RAMP (RATE * SFX_GAIN_RAMP_MS / 1000u)   /* ramp length in frames */

/* ------------------------------------------------------------------ *
 * synthetic clips
 * ------------------------------------------------------------------ */

/* strictly positive, so "how many frames came out" is readable from the data */
static int16_t *clip_pos(uint32_t n)
{
    int16_t *p = (int16_t *)malloc(n * sizeof *p);
    uint32_t i;
    for (i = 0; i < n; i++) p[i] = (int16_t)(500 + (i * 977u) % 12000u);
    return p;
}

/* both signs, never zero */
static int16_t *clip_bip(uint32_t n)
{
    int16_t *p = (int16_t *)malloc(n * sizeof *p);
    uint32_t i;
    for (i = 0; i < n; i++) {
        int v = (int)((i * 3121u + 7u) % 30000u) - 15000;
        p[i] = (int16_t)(v ? v : 1);
    }
    return p;
}

static int16_t *clip_const(uint32_t n, int v)
{
    int16_t *p = (int16_t *)malloc(n * sizeof *p);
    uint32_t i;
    for (i = 0; i < n; i++) p[i] = (int16_t)v;
    return p;
}

static SfxClip mkclip(int16_t *pcm, uint32_t frames, uint32_t rate)
{
    SfxClip c;
    c.pcm = pcm;
    c.frames = frames;
    c.rate = rate;
    return c;
}

/* Mixes one frame at a time (which also proves the mixer keeps no hidden
 * block state) until the voice is gone; returns the frames it produced. */
static int run_until_done(SfxPlayer *p, int h, int16_t *b, int cap)
{
    int k;
    for (k = 0; k < cap && sfx_active(p, h); k++) {
        b[0] = 0;
        sfx_mix_s16(p, b, 1);
    }
    return k;
}

/* ------------------------------------------------------------------ *
 * pitch 1, out_rate == clip rate must mix back out sample for sample
 * ------------------------------------------------------------------ */
static void test_exact_mix(void)
{
    SfxPlayer *p = sfx_player_create(RATE);
    SfxClip c = mkclip(clip_bip(64), 64, RATE);
    int16_t out[64];
    int h, i, exact = 1, added = 1, silent = 1;

    CHECK(p != NULL);
    h = sfx_play(p, &c, 1.0f, 1.0f, 0);
    CHECK(h > 0);
    memset(out, 0, sizeof out);
    sfx_mix_s16(p, out, 64);
    for (i = 0; i < 64; i++) if (out[i] != c.pcm[i]) exact = 0;
    CHECK(exact);                                   /* identity, not near-identity */
    CHECK(sfx_active(p, h) == 0);                   /* one-shot freed at the end */

    memset(out, 0, sizeof out);                     /* tail must be silence */
    sfx_mix_s16(p, out, 8);
    for (i = 0; i < 8; i++) if (out[i] != 0) silent = 0;
    CHECK(silent);

    h = sfx_play(p, &c, 1.0f, 1.0f, 0);             /* ADD, never overwrite */
    for (i = 0; i < 64; i++) out[i] = 1000;
    sfx_mix_s16(p, out, 64);
    for (i = 0; i < 64; i++) if (out[i] != c.pcm[i] + 1000) added = 0;
    CHECK(added);

    for (i = 0; i < 64; i++) out[i] = 1234;         /* idling leaves out alone */
    sfx_mix_s16(p, out, 64);
    {
        int kept = 1;
        for (i = 0; i < 64; i++) if (out[i] != 1234) kept = 0;
        CHECK(kept);
    }

    sfx_clip_free(&c);
    sfx_player_destroy(p);
}

/* ------------------------------------------------------------------ *
 * rate conversion and pitch change the produced length
 * ------------------------------------------------------------------ */
static void test_lengths(void)
{
    SfxPlayer *p = sfx_player_create(RATE);
    int16_t buf[512];
    int h, n;

    CHECK(p != NULL);
    /* 22050 -> 44100 doubles the frame count */
    {
        SfxClip c = mkclip(clip_pos(64), 64, 22050);
        int16_t out[128];
        int i, hits = 1, mids = 1;
        h = sfx_play(p, &c, 1.0f, 1.0f, 0);
        memset(out, 0, sizeof out);
        sfx_mix_s16(p, out, 128);
        CHECK(sfx_active(p, h) == 0);
        for (i = 0; i < 64; i++) if (out[2 * i] != c.pcm[i]) hits = 0;   /* every source sample lands */
        CHECK(hits);
        for (i = 0; i < 63; i++) {                  /* the in-betweens are interpolations */
            int lo = c.pcm[i] < c.pcm[i + 1] ? c.pcm[i] : c.pcm[i + 1];
            int hi = c.pcm[i] < c.pcm[i + 1] ? c.pcm[i + 1] : c.pcm[i];
            if (out[2 * i + 1] < lo || out[2 * i + 1] > hi) mids = 0;
        }
        CHECK(mids);
        CHECK(out[127] == c.pcm[63]);               /* last frame has no second tap */
        h = sfx_play(p, &c, 1.0f, 1.0f, 0);
        n = run_until_done(p, h, buf, 512);
        CHECK(n == 128);
        sfx_clip_free(&c);
    }
    /* pitch 2 halves it, pitch 0.5 doubles it */
    {
        SfxClip c = mkclip(clip_pos(64), 64, RATE);
        h = sfx_play(p, &c, 1.0f, 2.0f, 0);
        CHECK(h > 0);
        n = run_until_done(p, h, buf, 512);
        CHECK(n == 32);
        h = sfx_play(p, &c, 1.0f, 0.5f, 0);
        n = run_until_done(p, h, buf, 512);
        CHECK(n == 128);
        sfx_clip_free(&c);
    }
    /* pitch is clamped to 0.25..4 rather than trusted */
    {
        SfxClip c = mkclip(clip_pos(16), 16, RATE);
        h = sfx_play(p, &c, 1.0f, 1000.0f, 0);
        n = run_until_done(p, h, buf, 512);
        CHECK(n == 4);                              /* 16 / 4 */
        h = sfx_play(p, &c, 1.0f, 0.0f, 0);
        n = run_until_done(p, h, buf, 512);
        CHECK(n == 64);                             /* 16 / 0.25 */
        h = sfx_play(p, &c, 1.0f, -3.0f, 0);
        n = run_until_done(p, h, buf, 512);
        CHECK(n == 64);
        sfx_clip_free(&c);
    }
    /* retuning a live voice shortens what is left of it */
    {
        SfxClip c = mkclip(clip_pos(64), 64, RATE);
        int done = 0, k;
        h = sfx_play(p, &c, 1.0f, 1.0f, 0);
        for (k = 0; k < 32; k++) { buf[0] = 0; sfx_mix_s16(p, buf, 1); done++; }
        CHECK(sfx_active(p, h) == 1);
        sfx_set(p, h, 1.0f, 2.0f);
        n = run_until_done(p, h, buf, 512);
        CHECK(done + n == 48);                      /* 32 + ceil(32 / 2) */
        sfx_clip_free(&c);
    }
    sfx_player_destroy(p);
}

/* ------------------------------------------------------------------ *
 * looping, and a one-shot giving its voice back
 * ------------------------------------------------------------------ */
static void test_loop_and_release(void)
{
    SfxPlayer *p = sfx_player_create(RATE);
    int16_t out[200], buf[8];
    int h, i, all = 1;

    CHECK(p != NULL);
    {                                            /* loop keeps going, exactly */
        SfxClip c = mkclip(clip_pos(32), 32, RATE);
        memset(out, 0, sizeof out);
        h = sfx_play(p, &c, 1.0f, 1.0f, 1);
        CHECK(h > 0);
        sfx_mix_s16(p, out, 200);
        for (i = 0; i < 200; i++) if (out[i] != c.pcm[i % 32]) all = 0;
        CHECK(all);
        CHECK(sfx_active(p, h) == 1);              /* still playing past the end */
        sfx_stop(p, h);
        CHECK(sfx_active(p, h) == 0);
        memset(out, 0, sizeof out);
        sfx_mix_s16(p, out, 8);
        for (i = 0; i < 8; i++) if (out[i] != 0) all = 0;
        CHECK(all);                                /* stopped really silenced it */
        sfx_clip_free(&c);
    }
    {                                            /* the wrap interpolates, not clamps */
        SfxClip c = mkclip(clip_pos(32), 32, 22050);
        int a = c.pcm[31], b = c.pcm[0], mid = (a + b) / 2;
        memset(out, 0, sizeof out);
        h = sfx_play(p, &c, 1.0f, 1.0f, 1);
        sfx_mix_s16(p, out, 64);                   /* frame 63 reads 31.5, i.e. 31 -> 0 */
        CHECK(out[63] != c.pcm[31]);               /* a clamping tap would repeat 31 */
        CHECK(out[63] != c.pcm[0]);
        CHECK(out[63] > mid - 2 && out[63] < mid + 2);
        CHECK(sfx_active(p, h) == 1);
        sfx_stop_all(p);
        CHECK(sfx_active(p, h) == 0);
        sfx_clip_free(&c);
    }
    {                                            /* one-shot frees its slot for reuse */
        SfxClip a = mkclip(clip_pos(16), 16, RATE);
        SfxClip b = mkclip(clip_pos(24), 24, RATE);
        int h1 = sfx_play(p, &a, 1.0f, 1.0f, 0);
        int h2 = sfx_play(p, &b, 1.0f, 1.0f, 0);
        int h3, stale = 1;
        CHECK(h1 > 0 && h2 > 0 && h1 != h2);
        CHECK(run_until_done(p, h1, buf, 64) == 16);   /* h1 ends, h2 has 8 left */
        CHECK(sfx_active(p, h1) == 0 && sfx_active(p, h2) == 1);
        CHECK(run_until_done(p, h2, buf, 64) == 8);
        CHECK(sfx_active(p, h1) == 0 && sfx_active(p, h2) == 0);
        h3 = sfx_play(p, &a, 1.0f, 1.0f, 0);
        CHECK(h3 > 0 && h3 != h1);                 /* same slot, new generation */
        CHECK(sfx_active(p, h1) == 0);
        sfx_set(p, h1, 0.0f, 1.0f);                /* stale: must be inert */
        sfx_stop(p, h1);
        CHECK(sfx_active(p, h3) == 1);
        memset(out, 0, sizeof out);
        sfx_mix_s16(p, out, 8);
        for (i = 0; i < 8; i++) if (out[i] == 0) stale = 0;
        CHECK(stale);                              /* h3 is still audible */
        sfx_clip_free(&a);
        sfx_clip_free(&b);
    }
    sfx_player_destroy(p);
}

/* ------------------------------------------------------------------ *
 * the mix adds and saturates; it never wraps
 * ------------------------------------------------------------------ */
static void test_saturation(void)
{
    SfxPlayer *p = sfx_player_create(RATE);
    SfxClip loud = mkclip(clip_const(64, 30000), 64, RATE);
    SfxClip low  = mkclip(clip_const(64, -30000), 64, RATE);
    int16_t out[8];
    int i, k, ok;

    CHECK(p != NULL);
    sfx_play(p, &loud, 1.0f, 1.0f, 1);
    sfx_play(p, &loud, 1.0f, 1.0f, 1);
    memset(out, 0, sizeof out);
    sfx_mix_s16(p, out, 8);
    ok = 1;
    for (i = 0; i < 8; i++) if (out[i] != 32767) ok = 0;
    CHECK(ok);                                     /* +60000 clamps, does not wrap */
    sfx_stop_all(p);

    sfx_play(p, &low, 1.0f, 1.0f, 1);
    sfx_play(p, &low, 1.0f, 1.0f, 1);
    sfx_play(p, &low, 1.0f, 1.0f, 1);
    memset(out, 0, sizeof out);
    sfx_mix_s16(p, out, 8);
    ok = 1;
    for (i = 0; i < 8; i++) if (out[i] != -32768) ok = 0;
    CHECK(ok);                                     /* the negative rail is -32768 */
    sfx_stop_all(p);

    sfx_play(p, &loud, 1.0f, 1.0f, 1);
    sfx_play(p, &low, 1.0f, 1.0f, 1);
    memset(out, 0, sizeof out);
    sfx_mix_s16(p, out, 8);
    ok = 1;
    for (i = 0; i < 8; i++) if (out[i] != 0) ok = 0;
    CHECK(ok);                                     /* opposites cancel exactly */
    sfx_stop_all(p);

    for (k = 0; k < 12; k++) sfx_play(p, &loud, 1.0f, 1.0f, 1);   /* a pile */
    memset(out, 0, sizeof out);
    sfx_mix_s16(p, out, 8);
    ok = 1;
    for (i = 0; i < 8; i++) if (out[i] != 32767) ok = 0;
    CHECK(ok);
    sfx_stop_all(p);
    for (k = 0; k < 12; k++) sfx_play(p, &low, 1.0f, 1.0f, 1);
    memset(out, 0, sizeof out);
    sfx_mix_s16(p, out, 8);
    ok = 1;
    for (i = 0; i < 8; i++) if (out[i] != -32768) ok = 0;
    CHECK(ok);
    sfx_stop_all(p);

    sfx_clip_free(&loud);
    sfx_clip_free(&low);
    sfx_player_destroy(p);
}

/* ------------------------------------------------------------------ *
 * voice stealing: quietest one-shot, never a loop
 * ------------------------------------------------------------------ */
static void test_stealing(void)
{
    SfxPlayer *p = sfx_player_create(RATE);
    SfxClip hold = mkclip(clip_const(4000, 20000), 4000, RATE);
    SfxClip newc = mkclip(clip_const(4000, 8000), 4000, RATE);
    int h[SFX_MAX_VOICES], i, hn, ok = 1;
    int16_t out[8];

    CHECK(p != NULL);
    for (i = 0; i < SFX_MAX_VOICES; i++) {         /* 24 one-shots, distinct gains */
        h[i] = sfx_play(p, &hold, 0.001f * (float)(i + 1), 1.0f, 0);
        CHECK(h[i] > 0);
    }
    hn = sfx_play(p, &newc, 0.5f, 1.0f, 0);        /* 25th: something has to go */
    CHECK(hn > 0);
    CHECK(sfx_active(p, h[0]) == 0);               /* the quietest gave up its slot */
    CHECK(sfx_active(p, hn) == 1);
    for (i = 1; i < SFX_MAX_VOICES; i++) if (!sfx_active(p, h[i])) ok = 0;
    CHECK(ok);

    sfx_set(p, h[0], 1.0f, 1.0f);                  /* stale handle: no-op */
    sfx_stop(p, h[0]);
    CHECK(sfx_active(p, hn) == 1);
    for (i = 1; i < SFX_MAX_VOICES; i++) sfx_stop(p, h[i]);   /* leave only the thief */
    memset(out, 0, sizeof out);
    sfx_mix_s16(p, out, 8);
    ok = 1;
    for (i = 0; i < 8; i++) if (out[i] != 4000) ok = 0;       /* 8000 * 0.5, intact */
    CHECK(ok);

    /* loops are untouchable: nothing stealable means 0, not a stolen loop */
    sfx_stop_all(p);
    for (i = 0; i < SFX_MAX_VOICES; i++)
        h[i] = sfx_play(p, &hold, 0.1f, 1.0f, 1);
    CHECK(sfx_play(p, &newc, 0.5f, 1.0f, 0) == 0);
    ok = 1;
    for (i = 0; i < SFX_MAX_VOICES; i++) if (!sfx_active(p, h[i])) ok = 0;
    CHECK(ok);

    /* ... and even a loop that is quieter than the one-shot is not the victim */
    sfx_stop(p, h[5]);
    {
        int hs = sfx_play(p, &hold, 0.3f, 1.0f, 0);
        int hz = sfx_play(p, &newc, 0.5f, 1.0f, 0);
        CHECK(hs > 0 && hz > 0);
        CHECK(sfx_active(p, hs) == 0);
        CHECK(sfx_active(p, hz) == 1);
        ok = 1;
        for (i = 0; i < SFX_MAX_VOICES; i++)
            if (i != 5 && !sfx_active(p, h[i])) ok = 0;
        CHECK(ok);
    }
    sfx_stop_all(p);
    sfx_clip_free(&hold);
    sfx_clip_free(&newc);
    sfx_player_destroy(p);
}

/* ------------------------------------------------------------------ *
 * sfx_set slews the gain instead of stepping it
 * ------------------------------------------------------------------ */
static void test_gain_ramp(void)
{
    SfxPlayer *p = sfx_player_create(RATE);
    SfxClip c = mkclip(clip_const(4000, 8000), 4000, RATE);
    int16_t out[600];
    int h, i, maxstep = 0, monotone = 1, ramped = 0;
    int allowed = (int)((8000 + RAMP - 1) / RAMP);  /* per-frame slew limit */

    CHECK(p != NULL);
    CHECK(RAMP >= 100 && RAMP <= 500);              /* ~5 ms at 44100 */
    h = sfx_play(p, &c, 0.0f, 1.0f, 0);
    CHECK(h > 0);
    sfx_set(p, h, 1.0f, 1.0f);
    memset(out, 0, sizeof out);
    sfx_mix_s16(p, out, (int)RAMP + 2);
    CHECK(out[0] == 0);                             /* nothing jumps on frame 0 */
    for (i = 1; i <= (int)RAMP + 1; i++) {
        int d = out[i] - out[i - 1];
        if (d > maxstep) maxstep = d;
        if (d < 0) monotone = 0;
        if (out[i] > 0 && out[i] < 8000) ramped = 1;
    }
    CHECK(monotone);
    CHECK(ramped);                                  /* a ramp, not a step */
    CHECK(maxstep <= allowed);                      /* never faster than 5 ms */
    CHECK(out[(int)RAMP - 1] < 8000);
    CHECK(out[(int)RAMP] == 8000);                  /* and it does arrive */
    CHECK(sfx_active(p, h) == 1);

    sfx_set(p, h, 0.0f, 1.0f);                      /* ramp back down */
    memset(out, 0, sizeof out);
    sfx_mix_s16(p, out, (int)RAMP + 2);
    maxstep = 0;
    for (i = 1; i <= (int)RAMP + 1; i++) {
        int d = out[i - 1] - out[i];
        if (d > maxstep) maxstep = d;
    }
    CHECK(maxstep <= allowed);
    CHECK(out[(int)RAMP] == 0);
    CHECK(sfx_active(p, h) == 1);                   /* silence is not the end */

    /* retargeting mid-ramp may not jump either */
    sfx_set(p, h, 1.0f, 1.0f);
    sfx_mix_s16(p, out, 10);
    sfx_set(p, h, 0.2f, 1.0f);
    memset(out, 0, sizeof out);
    sfx_mix_s16(p, out, (int)RAMP + 2);
    maxstep = 0;
    for (i = 1; i <= (int)RAMP + 1; i++) {
        int d = out[i] - out[i - 1];
        if (d < 0) d = -d;
        if (d > maxstep) maxstep = d;
    }
    CHECK(maxstep <= allowed);
    CHECK(out[(int)RAMP + 1] == 1600);              /* 8000 * 0.2 */
    sfx_clip_free(&c);
    sfx_player_destroy(p);
}

/* ------------------------------------------------------------------ *
 * NULL / empty input must never crash
 * ------------------------------------------------------------------ */
static void test_no_crash(void)
{
    SfxPlayer *p;
    SfxClip c, empty;
    int16_t out[8] = { 0 };

    CHECK(sfx_player_create(0) == NULL);
    sfx_player_destroy(NULL);
    memset(&empty, 0, sizeof empty);
    memset(out, 0, sizeof out);

    sfx_clip_free(NULL);
    sfx_clip_free(&empty);
    sfx_clip_free(&empty);

    CHECK(sfx_play(NULL, &empty, 1.0f, 1.0f, 0) == 0);
    CHECK(sfx_clip_from_bank(NULL, NULL, 0) == 0);
    p = sfx_player_create(RATE);
    CHECK(p != NULL);
    CHECK(sfx_play(p, NULL, 1.0f, 1.0f, 0) == 0);
    CHECK(sfx_play(p, &empty, 1.0f, 1.0f, 0) == 0);       /* frames == 0 */
    c = mkclip(clip_pos(16), 16, 0);
    CHECK(sfx_play(p, &c, 1.0f, 1.0f, 0) == 0);           /* rate == 0 */
    free(c.pcm);
    c = mkclip(NULL, 16, RATE);
    CHECK(sfx_play(p, &c, 1.0f, 1.0f, 0) == 0);           /* pcm == NULL */
    CHECK(sfx_active(p, 0) == 0);
    CHECK(sfx_active(p, -1) == 0);
    CHECK(sfx_active(p, 1 << 30) == 0);
    sfx_set(p, 0, 1.0f, 1.0f);
    sfx_set(p, -7, 1.0f, 1.0f);
    sfx_set(p, 123456, 1.0f, 0.5f);
    sfx_stop(p, 0);
    sfx_stop(p, 123456);
    sfx_mix_s16(NULL, out, 8);
    sfx_mix_s16(p, NULL, 8);
    sfx_mix_s16(p, out, 0);
    sfx_mix_s16(p, out, -8);
    sfx_stop_all(NULL);
    CHECK(1);                                            /* got here without crashing */

    /* a clamp, not a crash: NaN gain is silence, NaN pitch is the floor */
    {
        SfxClip k = mkclip(clip_const(64, 10000), 64, RATE);
        int h = sfx_play(p, &k, NAN, NAN, 0);
        int i, silent = 1;
        CHECK(h > 0);
        memset(out, 0, sizeof out);
        sfx_mix_s16(p, out, 8);
        for (i = 0; i < 8; i++) if (out[i] != 0) silent = 0;
        CHECK(silent);
        CHECK(sfx_active(p, h) == 1);                    /* pitch 0.25, still running */
        sfx_stop_all(p);
        sfx_clip_free(&k);
    }
    sfx_player_destroy(p);
}

/* ------------------------------------------------------------------ *
 * a hand-made ABK, so the bank -> clip -> play seam is covered too
 * (identical builder to tools/sfx_bank_test.c, which is not shared)
 * ------------------------------------------------------------------ */
typedef struct { unsigned char *p; size_t at, cap; } Buf;

static void w8(Buf *b, unsigned v)   { if (b->at < b->cap) b->p[b->at] = (unsigned char)v; b->at++; }
static void w32le(Buf *b, uint32_t v) { w8(b, v); w8(b, v >> 8); w8(b, v >> 16); w8(b, v >> 24); }
static void w16be(Buf *b, int v)      { w8(b, (unsigned)v >> 8); w8(b, (unsigned)v & 0xFF); }
static void wpad(Buf *b, size_t to)   { while (b->at < to) w8(b, 0); }

static void wpt(Buf *b, size_t end_at, uint32_t frames, int with_rate, uint32_t rate,
                uint32_t data_off)
{
    b->at += 4;                                       /* caller patches "PT\0\0" */
    w8(b, 0x06); w8(b, 1); w8(b, 90);
    w8(b, 0x13); w8(b, 1); w8(b, 127);
    w8(b, 0x85); w8(b, 2); w8(b, frames >> 8); w8(b, frames);
    if (with_rate)  { w8(b, 0x84); w8(b, 2); w8(b, rate >> 8); w8(b, rate); }
    w8(b, 0x80); w8(b, 1); w8(b, 2);
    w8(b, 0x8a); w8(b, 4); w8(b, 0); w8(b, 0); w8(b, 0); w8(b, 0);
    w8(b, 0x88); w8(b, 4);
    w8(b, data_off >> 24); w8(b, data_off >> 16); w8(b, data_off >> 8); w8(b, data_off);
    w8(b, 0xFD);
    w8(b, 0xFF);
    wpad(b, end_at);
}

#define BANK_OFF   0x40
#define PT0        0x20
#define PT1        0x44
#define DATA_EE    0x68
#define DATA_ADPCM 0xA8
#define BANK_LEN   0xB8

static size_t build_abk(unsigned char *out, size_t cap)
{
    Buf al = { out, 0, cap };
    size_t pt[2] = { BANK_OFF + PT0, BANK_OFF + PT1 };
    size_t dt[2] = { BANK_OFF + DATA_EE, BANK_OFF + DATA_ADPCM };
    size_t bank;
    int k;

    memcpy(out, "ABKC", 4);
    al.at = 4;
    w8(&al, 1); w8(&al, 1); w8(&al, 1); w8(&al, 0);
    w32le(&al, 0x20000); w32le(&al, 0); w32le(&al, 0);
    w32le(&al, BANK_OFF + BANK_LEN);
    w32le(&al, BANK_OFF);
    w32le(&al, 0);
    w32le(&al, BANK_OFF);
    w32le(&al, BANK_LEN);
    wpad(&al, BANK_OFF);

    bank = al.at;
    memcpy(out + bank, "BNKl", 4);
    al.at = bank + 4;
    w8(&al, 5); w8(&al, 0);
    w8(&al, 3); w8(&al, 0);                            /* 2 records + 1 */
    w32le(&al, DATA_ADPCM + 15);
    w32le(&al, 0); w32le(&al, 0);
    for (k = 0; k < 2; k++) {
        al.at = bank + 0x18 + 4 * (size_t)k;
        w32le(&al, (uint32_t)(pt[k] - bank - 0x18 - 4 * k));
    }
    for (k = 0; k < 2; k++) {
        al.at = pt[k];
        wpt(&al, pt[k] + 0x24, 28, k == 0, 32000, (uint32_t)(dt[k] - bank));
        memcpy(out + pt[k], "PT\0\0", 4);
    }
    al.at = dt[0];                                     /* one raw 0xEE frame */
    w8(&al, 0xEE);
    w16be(&al, -1234);
    w16be(&al, 567);
    for (k = 0; k < 28; k++) w16be(&al, k * 137 - 1800);
    al.at = dt[1];                                     /* one ADPCM frame */
    w8(&al, 0x28);
    for (k = 1; k < 15; k++) w8(&al, (unsigned char)((k * 0x9E + 0x31) & 0xFF));
    al.at = BANK_OFF + BANK_LEN;
    return al.at <= cap ? al.at : 0;
}

static void test_clip_from_bank(void)
{
    unsigned char file[0x400];
    size_t len = build_abk(file, sizeof file);
    SfxBank b;
    SfxClip c;
    int h, k, exact = 1;
    int16_t buf[8];
    SfxPlayer *p = sfx_player_create(RATE);

    CHECK(len == BANK_OFF + BANK_LEN);
    CHECK(sfx_bank_open_mem(&b, file, len) == 1);
    CHECK(p != NULL);
    if (b.count != 2) { printf("  count was %d, error '%s'\n", b.count, b.error); }
    CHECK(b.count == 2);

    CHECK(sfx_clip_from_bank(&c, &b, 0) == 1);         /* the raw frame */
    CHECK(c.frames == 28 && c.rate == 32000 && c.pcm != NULL);
    for (k = 0; k < 28; k++) if (!c.pcm || c.pcm[k] != k * 137 - 1800) exact = 0;
    CHECK(exact);

    h = sfx_play(p, &c, 1.0f, 1.0f, 0);                /* 32000 -> 44100 */
    CHECK(h > 0);
    CHECK(run_until_done(p, h, buf, 512) == 39);       /* ceil(28 / (32000/44100)) */
    sfx_clip_free(&c);
    CHECK(c.pcm == NULL && c.frames == 0 && c.rate == 0);

    CHECK(sfx_clip_from_bank(&c, &b, 1) == 1);         /* the ADPCM frame */
    CHECK(c.frames == 28 && c.rate == 22050 && c.pcm != NULL);
    {
        int nz = 0;
        for (k = 0; c.pcm && k < 28; k++) if (c.pcm[k]) nz = 1;
        CHECK(nz);                                     /* decoded to something */
    }
    sfx_clip_free(&c);

    CHECK(sfx_clip_from_bank(&c, &b, -1) == 0 && c.pcm == NULL);
    CHECK(sfx_clip_from_bank(&c, &b, 2) == 0 && c.pcm == NULL);
    CHECK(sfx_clip_from_bank(&c, NULL, 0) == 0);
    sfx_bank_close(&b);

    {                                                  /* an all-zero bank opens as empty */
        SfxBank z;
        memset(&z, 0, sizeof z);
        CHECK(sfx_clip_from_bank(&c, &z, 0) == 0 && c.pcm == NULL);
        z.count = 1;                                   /* sample declared but no image */
        z.samples = (SfxSample *)calloc(1, sizeof *z.samples);
        CHECK(z.samples != NULL);
        if (z.samples) {
            z.samples[0].frames = 4;
            z.samples[0].decodable = 1;
            CHECK(sfx_clip_from_bank(&c, &z, 0) == 0);  /* decode fails, nothing leaks */
            CHECK(c.pcm == NULL);
            free(z.samples);
        }
    }
    sfx_player_destroy(p);
}

int main(void)
{
    test_exact_mix();
    test_lengths();
    test_loop_and_release();
    test_saturation();
    test_stealing();
    test_gain_ramp();
    test_no_crash();
    test_clip_from_bank();

    printf("sfx_play_test: %d checks, %d failures\n", nchecks, nfail);
    printf("%s\n", nfail ? "FAIL" : "PASS");
    return nfail ? 1 : 0;
}
